ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| ImageFileName=/(vssadmin|wmic|bcdedit|wbadmin|powershell|net|sc|taskkill)\.exe$/i
| (regex("(?i)(delete shadows|shadowcopy delete|delete catalog|bootstatuspolicy ignoreallfailures|recoveryenabled no|DisableRealtimeMonitoring|DisableBehaviorMonitoring|Add-MpPreference -ExclusionPath)", field=CommandLine)
   OR (ImageFileName=/\\net\.exe$/i AND regex("(?i)stop.*(veeam|mssql|sqlagent|backup|msexchange|sophos|savadminservice|avp)", field=CommandLine))
   OR (ImageFileName=/\\taskkill\.exe$/i AND regex("(?i)(sqlservr|sqlwriter|veeam|backup|agntsvc)", field=CommandLine)))
| case {
    regex("(?i)(delete shadows|shadowcopy delete|delete catalog)", field=CommandLine) | Tactic := "ShadowWipe";
    regex("(?i)(bootstatuspolicy ignoreallfailures|recoveryenabled no)", field=CommandLine) | Tactic := "RecoveryKill";
    regex("(?i)(DisableRealtimeMonitoring|DisableBehaviorMonitoring|MpPreference -Disable|Add-MpPreference -ExclusionPath)", field=CommandLine) | Tactic := "DefenderTamper";
    * | Tactic := "ServiceKill";
  }
| groupBy([aid, ComputerName, UserName, bucket(span=5m)], function=[collect_set(Tactic, as=Tactics), count_distinct(Tactic, as=TacticCount), collect([CommandLine], limit=50)])
| TacticCount>=3
